import 'package:flutter/widgets.dart';
import 'package:flutter_svg/flutter_svg.dart';

import '../../app/theme/recipix_tokens.dart';

/// Hand-drawn UI icons in `assets/icons/` (generated by `tool/gen_icons.sh`).
enum RecipixIcons {
  home,
  fridge,
  scan,
  random,
  dashboard,
  plus,
  minus,
  check,
  close,
  chevronRight,
  chevronLeft,
  trash,
  lock,
  unlock,
  undo,
  barcode,
  receipt,
  leaf,
  clock,
  pan,
  wallet,
  tag,
  bowl,
  basket;

  String get asset {
    final file = name.replaceAllMapped(
      RegExp('[A-Z]'),
      (m) => '_${m[0]!.toLowerCase()}',
    );
    return 'assets/icons/$file.svg';
  }
}

/// Draws a [RecipixIcons] glyph in the ambient [IconTheme] color unless
/// [color] is given. Decorative by default; pass [semanticLabel] when the
/// icon carries meaning on its own.
class RecipixIcon extends StatelessWidget {
  const RecipixIcon(
    this.icon, {
    super.key,
    this.color,
    this.size = RecipixTokens.iconSize,
    this.semanticLabel,
  });

  final RecipixIcons icon;
  final Color? color;
  final double size;
  final String? semanticLabel;

  @override
  Widget build(BuildContext context) {
    final c = color ?? IconTheme.of(context).color ?? context.tokens.ink;
    return SvgPicture.asset(
      icon.asset,
      width: size,
      height: size,
      theme: SvgTheme(currentColor: c),
      semanticsLabel: semanticLabel,
      excludeFromSemantics: semanticLabel == null,
    );
  }
}
